def append(list1, list2):
    if list1 == []:
        return list2
    return [list1[0]] + append(list1[1:], list2)


def concat(lists):
    if lists == []:
        return []
    return append(lists[0], concat(lists[1:]))


def filter(function, list):
    if list == []:
        return []
    head, tail = list[0], list[1:]
    if function(head):
        return [head] + filter(function, tail)
    return filter(function, tail)


def length(list):
    if list == []:
        return 0
    return 1 + length(list[1:])


def map(function, list):
    if list == []:
        return []
    return [function(list[0])] + map(function, list[1:])


def foldl(function, list, initial):
    acc = initial
    for el in list:
        acc = function(acc, el)
    return acc


def foldr(function, list, initial):
    acc = initial
    for el in reverse(list):
        acc = function(acc, el)
    return acc


def reverse(list):
    if list == []:
        return []
    return reverse(list[1:]) + [list[0]]
